<?php
require dirname(__DIR__).'/bootstrap.php';require __DIR__.'/admin-layout.php';admin_required();$keys=['store_name','store_description','store_email','store_whatsapp','store_address','instagram','tiktok','announcement','footer_text','shipping_fee'];if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();foreach($keys as $k){$q=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$q->execute([$k,trim($_POST[$k]??'')]);}flash('Store settings saved.');redirect('settings.php');}admin_header('Store settings');$f=get_flash();if($f)echo '<div class="notice">'.e($f['message']).'</div>'; ?><form method="post" class="admin-form admin-panel"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><?php foreach($keys as $k):?><label><?=e(ucwords(str_replace('_',' ',$k)))?><input name="<?=$k?>" value="<?=e(setting($pdo,$k))?>"></label><?php endforeach;?><button class="button">SAVE SETTINGS</button></form><?php admin_footer(); ?>
